oxy_webhelp_navlinks = {"tocId-d39536e14855":{"topics":[{"title":"Adding a secret-based AWS KMS key manager","shortdesc":"<p class=\"shortdesc\">Add a secret-based AWS key manager for <span class=\"ph\">RSC<\/span> to access your AWS KMS key         using IAM credentials for data center archival locations.<\/p>","href":"saas\/adding_aws_kms_manager.html","attributes":{"data-id":"adding_aws_kms_manager"},"menu":{"hasChildren":false},"tocID":"adding_aws_kms_manager-d39536e14856","next":"adding_aws_kms_manager-d39536e14856"},{"title":"Adding Azure Key Vaults","shortdesc":"<p class=\"shortdesc\">Add an Azure Key Vault to manage encryption for Azure based archives or Rubrik Cloud         Vault. You can configure the integration using secretless provisioning or secret-based         provisioning.<\/p>","href":"saas\/adding_akv.html","attributes":{"data-id":"adding_akv"},"menu":{"hasChildren":false},"tocID":"adding_akv-d39536e14895","next":"adding_akv-d39536e14895"},{"title":"Adding a cloud account-based Google Cloud KMS key manager","shortdesc":"<p class=\"shortdesc\">Add a cloud account-based key manager to give <span class=\"ph\">RSC<\/span> access to your         Google Cloud Key Management Service key for client-side encrypted cloud-native archival         locations.<\/p>","href":"saas\/adding_gcp_cloud_account_kms_manager.html","attributes":{"data-id":"adding_gcp_cloud_account_kms_manager"},"menu":{"hasChildren":false},"tocID":"adding_gcp_cloud_account_kms_manager-d39536e14964","next":"adding_gcp_cloud_account_kms_manager-d39536e14964"},{"title":"Adding KMIP servers","shortdesc":"<p class=\"shortdesc\">To manage your Key Encryption Key and self-encrypting drive passwords on a Rubrik         cluster using a KMIP-compliant external key manager, you must add the details of the KMIP         server in <span class=\"ph\">RSC<\/span>.<\/p>","href":"saas\/adding_kmip_server.html","attributes":{"data-id":"adding_kmip_server"},"menu":{"hasChildren":false},"tocID":"adding_kmip_server-d39536e14989","next":"adding_kmip_server-d39536e14989"}]}};